import{u as h,p as g,o as p,c as m,a6 as f,dL as y,dM as b}from"./chunks/framework.DXKRSLBS.js";function x(d){const e=new Date(d);e.setHours(0,0,0,0);const o=document.getElementById("schedule-table");if(o)for(const n of o.tBodies[0].rows){const a=n.cells[0],l=/^(\d+)([AB])$/i.exec(a.textContent.trim());if(l){const i=parseInt(l[1],10),s=(l[2].toUpperCase()==="A"?1:3)+(i-1)*7,t=new Date(e);t.setDate(e.getDate()+s);const r=`${t.getMonth()+1}/${t.getDate()}`;a.textContent=`${a.textContent} (${r})`}else{const i=/^(\d+)$/i.exec(a.textContent.trim());if(i){const s=(parseInt(i[1],10)-1)*7,t=new Date(e);t.setDate(e.getDate()+s);const r=new Date(e);r.setDate(e.getDate()+s+4);const u=`${t.getMonth()+1}/${t.getDate()} – ${r.getMonth()+1}/${r.getDate()}`;a.textContent=`${a.textContent} (${u})`}}}}const k=JSON.parse('{"title":"Syllabus | CSCI 315 Data Structure Analysis","description":"","frontmatter":{"head":[["style",{"type":"text/css"},"#pdf { display: inline-block;position: relative; left: 50%; transform: translateX(-50%); margin-top:0.5em; padding: 3px 6px; font-size: 14pt; background-color: var(--vp-button-brand-bg); border: var(--vp-button-brand-border) 1px solid; border-radius: 5px; color: var(--vp-button-brand-text);}"]],"schedule_start_date":"2026-08-24","start_week":1,"date":"Fall of 2026"},"headers":[],"relativePath":"syllabus.md","filePath":"syllabus.md","lastUpdated":1785807638000}'),w={name:"syllabus.md"},C=Object.assign(w,{setup(d){const{frontmatter:e}=h();return g(()=>{x(e.value.schedule_start_date)}),(o,n)=>(p(),m("div",null,[...n[0]||(n[0]=[f('<h1 id="syllabus-csci-315-data-structure-analysis" tabindex="-1">Syllabus | CSCI 315 <em>Data Structure Analysis</em> <a class="header-anchor" href="#syllabus-csci-315-data-structure-analysis" aria-label="Permalink to “Syllabus | CSCI 315 Data Structure Analysis”">​</a></h1><figure class="light-only"><img src="'+y+'" alt="Charleston Southern University" class="light-only"></figure><figure class="dark-only"><img src="'+b+'" alt="Charleston Southern University" class="dark-only"></figure><p><a href="syllabus.pdf" download="Syllabus-CSCI315.pdf" id="pdf">Download Printable Version</a></p><h2 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to “General Information”">​</a></h2><p><strong>Department</strong>: Computer Science<br><strong>Course Name</strong>: Data Structure Analysis<br><strong>Course Number</strong>: CSCI 315<br><strong>Credit Hours</strong>: 4 credit hours; 3 lecture hours and 2 laboratory hours.<br><strong>Approved Major Credit</strong>: BS in Computer Science, BS in Cybersecurity, BA in Applied Computing, BT in Computer Science, and BT in Cybersecurity<br><strong>LAC Requirement</strong>: None<br><strong>Prerequisites</strong>: CSCI 325 with a grade of ‘C’ or better.</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to “Course Description”">​</a></h2><p>The effective application of data structures and abstract data types. Abstract data types studied include lists, stacks, queues, and trees. Implementation methods include arrays, classes, pointers, and recursion. Analysis methods include Big-O notation using induction and recurrence relations. Topics also include ethical issues in computer science. (C++ is currently used.)</p><h3 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h3><p>This course is designed to teach you many of the basic data structures used in computer science. You will learn how to make them, use them, and analyze them. In addition, you will see how to apply them to novel problems using careful analysis of the problem to determine which data structure is best suited. Coding will be done in C++, but the concepts are not language-dependent.</p><p>This course is one of the most important in the major. Projects will require a level of design that is new to your programming career and will help to prepare you for real-world jobs. The ‘toolbox’ this class will provide you will be used throughout your programming future. The course serves as a gateway to many advanced courses. CSCI 315 is a <em>demanding</em> course, expect more work than previous courses. The projects in this class are more involved, requiring a deeper understanding of Computer Science. Learning to design and manage large projects is a core concept of the degree.</p><h2 id="course-materials" tabindex="-1">Course Materials <a class="header-anchor" href="#course-materials" aria-label="Permalink to “Course Materials”">​</a></h2><h3 id="required-textbook" tabindex="-1">Required Textbook <a class="header-anchor" href="#required-textbook" aria-label="Permalink to “Required Textbook”">​</a></h3><p>Malik, D. S. (2018). <a href="https://www.cengage.com/c/student/9781337117562/" target="_blank" rel="noreferrer">C++ Programming: Program Design Including Data Structures</a>. 8th edition. Stamford, CT: Cengage Learning. ISBN: 978-1-337-11756-2. <em>You may also choose to purchase the cheaper 7th edition for this course.</em></p><h3 id="other-required-materials" tabindex="-1">Other Required Materials <a class="header-anchor" href="#other-required-materials" aria-label="Permalink to “Other Required Materials”">​</a></h3><p>This course relies on <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a>. Assignments and lectures are located on GitHub at <a href="https://github.com/csu-cs/CSCI-315-2026-Fall" target="_blank" rel="noreferrer">https://github.com/csu-cs/CSCI-315-2026-Fall</a>. If you cannot access it, please email me so I can grant you access.</p><h2 id="student-learning-outcomes" tabindex="-1">Student Learning Outcomes <a class="header-anchor" href="#student-learning-outcomes" aria-label="Permalink to “Student Learning Outcomes”">​</a></h2><p>By the conclusion of this course, students will be able to:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>#</strong></th><th style="text-align:left;"><strong>Student Learning Outcome</strong></th><th style="text-align:center;"><strong>ABET-CAC SLO Alignment</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;">Navigate a Unix/Linux environment using command-line interface tools, compile C++ programs using compiler tools (like GCC/Clang and Makefiles), and manage source code repositories using Git.</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">Allocate, manage, and deallocate memory dynamically in C++, and utilize diagnostic tools to detect and resolve memory leaks, segmentation faults, and pointer errors.</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">Design and execute automated unit tests that cover normal, edge, and failure cases to verify software correctness and prevent regressions.</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">Implement robust software components in C++ using core object-oriented principles, including classes, encapsulation, inheritance, operator overloading, and templates (parametric polymorphism).</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">Quantify and compare the computational efficiency of algorithms and data structures analytically using Big-O notation, recurrence relations, and induction, as well as empirically through execution timing.</td><td style="text-align:center;">1, 6</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">Implement and manipulate basic linear data structures, including singly-linked lists, doubly-linked lists, stacks, and queues.</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;">Implement and manipulate hierarchical and specialized trees, including Binary Search Trees (BST), Heaps, B-Trees, and Quadtrees.</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">Represent graphs using adjacency lists and adjacency matrices, and apply graph search algorithms (Depth-First Search and Breadth-First Search) to solve pathfinding and spatial search problems.</td><td style="text-align:center;">1, 2, 6</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">Select, implement, and evaluate quadratic (bubble, selection, insertion) and divide-and-conquer (merge, quick) sorting algorithms, along with linear and binary search methods.</td><td style="text-align:center;">1, 2, 6</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">Design and implement hash tables, analyzing the performance tradeoffs between chaining and open-addressing collision resolution strategies.</td><td style="text-align:center;">1, 2, 6</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;">Appropriately integrate standard containers, iterators, and generic algorithms from the C++ Standard Template Library (STL) to construct efficient software systems.</td><td style="text-align:center;">2, 6</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;">Evaluate the ethical, legal, and professional implications of computing practices, particularly regarding software reliability, testing standards, and academic integrity.</td><td style="text-align:center;">4</td></tr></tbody></table><h3 id="abet-cac-student-outcomes-reference" tabindex="-1">ABET-CAC Student Outcomes Reference <a class="header-anchor" href="#abet-cac-student-outcomes-reference" aria-label="Permalink to “ABET-CAC Student Outcomes Reference”">​</a></h3><p>The following ABET Computing Accreditation Commission (CAC) student outcomes are supported by this course. Students completing this course will have the ability to:</p><table tabindex="0"><thead><tr><th><strong>#</strong></th><th><strong>Student Learning Outcome</strong></th></tr></thead><tbody><tr><td>1</td><td>Analyze a complex computing problem and apply principles of computing and other relevant disciplines to identify solutions.</td></tr><tr><td>2</td><td>Design, implement, and evaluate a computing-based solution to meet a given set of computing requirements in the context of the program’s discipline.</td></tr><tr><td>3</td><td>Communicate effectively in a variety of professional contexts.</td></tr><tr><td>4</td><td>Recognize professional responsibilities and make informed judgments in computing practice based on legal and ethical principles.</td></tr><tr><td>6</td><td>Apply computer science theory and software development fundamentals to produce computing-based solutions.</td></tr></tbody></table><h2 id="tentative-weekly-schedule" tabindex="-1">Tentative Weekly Schedule <a class="header-anchor" href="#tentative-weekly-schedule" aria-label="Permalink to “Tentative Weekly Schedule”">​</a></h2><p>The weekly schedule is subject to change. <strong>Those who keep up with the work generally do well.</strong></p><table id="schedule-table" tabindex="0"><thead><tr><th style="text-align:center;">Day</th><th>Lectures</th><th>Related Assignment</th></tr></thead><tbody><tr><td style="text-align:center;">1A</td><td><a href="/csci-315/lectures/01-introduction">Introduction</a> and <a href="/csci-315/lectures/01-basic-unix">Unix/Linux Commands</a></td><td>Lab 01</td></tr><tr><td style="text-align:center;">1B</td><td><a href="/csci-315/lectures/02-unix-compilation">C++ Compilation is Linux</a></td><td>Lab 02</td></tr><tr><td style="text-align:center;">2A</td><td><a href="/csci-315/lectures/03-memory-management">Memory Management</a></td><td>Lab 03</td></tr><tr><td style="text-align:center;">2B</td><td><a href="/csci-315/lectures/04-pointers">Pointers</a> and <a href="/csci-315/lectures/04-testing">Testing</a></td><td>Lab 04, 05, &amp; Ethics</td></tr><tr><td style="text-align:center;">3A</td><td><a href="/csci-315/lectures/05-oop">C++ Object-Oriented Programming</a></td><td></td></tr><tr><td style="text-align:center;">3B</td><td><a href="/csci-315/lectures/06-operator-overloading">Operator Overloading</a> and <a href="/csci-315/lectures/06-templates">Templates</a></td><td>Lab 06</td></tr><tr><td style="text-align:center;">4A</td><td><a href="/csci-315/lectures/07-empirical-analysis">Empirical Analysis</a> and <a href="/csci-315/lectures/07-analytical-analysis">Analytical Analysis</a></td><td>Lab 07</td></tr><tr><td style="text-align:center;">4B</td><td><a href="/csci-315/lectures/08-linked-lists">Linked Lists</a></td><td>Lab 08</td></tr><tr><td style="text-align:center;">5A</td><td><a href="/csci-315/lectures/09-debugging">Debugging</a> and <a href="/csci-315/lectures/09-doubly-linked-lists">Doubly-Linked Lists, &amp; the STL</a></td><td>Project 1 &amp; Lab 09</td></tr><tr><td style="text-align:center;">5B</td><td><a href="/csci-315/lectures/10-search">Search</a> and <a href="/csci-315/lectures/10-quadratic-sort">Quadratic Sorting</a></td><td>Lab 10</td></tr><tr><td style="text-align:center;">6A</td><td><a href="/csci-315/lectures/11-quick-sort">Quick Sort</a> and <a href="/csci-315/lectures/11-merge-sort">Merge Sort</a></td><td>Lab 11</td></tr><tr><td style="text-align:center;">6B</td><td><a href="/csci-315/lectures/12-stacks">Stacks</a>, <a href="/csci-315/lectures/12-queues">Queues</a>, <a href="/csci-315/guides/midterm-study-guide">Midterm Study Guide</a></td><td>Lab 12</td></tr><tr><td style="text-align:center;">7A</td><td><a href="/csci-315/lectures/13-2D-search">Depth- and Breadth-First Search (2D Maze Search)</a></td><td><a href="/csci-315/lectures/13-project2">Project 2</a> &amp; Lab 13</td></tr><tr><td style="text-align:center;">7B</td><td>Midterm Exam</td><td></td></tr><tr><td style="text-align:center;">8A</td><td><em>Fall Break</em> (No Class)</td><td></td></tr><tr><td style="text-align:center;">8B</td><td>Binary Search Trees: <a href="/csci-315/lectures/14-binary-trees-1">Insertion, Search</a> and <a href="/csci-315/lectures/14-binary-trees-traversal">Intro to Traversal</a></td><td>Lab 14</td></tr><tr><td style="text-align:center;">9A</td><td>Binary Search Trees: <a href="/csci-315/lectures/15-binary-trees-delete">Deletion</a> and <a href="/csci-315/lectures/15-binary-trees-traversal">Generic Traversal</a></td><td>Lab 15</td></tr><tr><td style="text-align:center;">9B</td><td><a href="/csci-315/lectures/16-heaps-heapsort">Heaps &amp; Heapsort</a></td><td>Lab 16</td></tr><tr><td style="text-align:center;">10A</td><td><a href="/csci-315/lectures/17-stl-containers">STL Containers and Iterators</a> and <a href="/csci-315/lectures/17-stl-algorithms">STL Algorithms</a></td><td>Lab 17</td></tr><tr><td style="text-align:center;">10B</td><td><a href="/csci-315/lectures/18-hash-tables-chaining">Hash Tables via Chaining</a></td><td>Lab 18</td></tr><tr><td style="text-align:center;">11A</td><td><a href="/csci-315/lectures/19-project3">Project 3</a> and <a href="/csci-315/lectures/19-hash-tables-open-addressing">Hash Tables via Open-Addressing</a></td><td><a href="/csci-315/lectures/19-project3">Project 3</a> &amp; Lab 19</td></tr><tr><td style="text-align:center;">11B</td><td><a href="/csci-315/lectures/20-priority-queues">Priority Queues</a></td><td>Lab 20</td></tr><tr><td style="text-align:center;">12A</td><td><a href="/csci-315/lectures/21-b-trees">B-Trees</a></td><td>Lab 21</td></tr><tr><td style="text-align:center;">12B</td><td><a href="/csci-315/lectures/22-graphs-adjacency-matrices">Graphs via Adjacency Matrices</a></td><td>Lab 22</td></tr><tr><td style="text-align:center;">13A</td><td><a href="/csci-315/lectures/23-graphs-adjacency-lists">Graphs via Adjacency Lists</a></td><td>Lab 23</td></tr><tr><td style="text-align:center;">13B</td><td><a href="/csci-315/lectures/24-quadtrees">Quadtrees</a></td><td>Lab 24</td></tr><tr><td style="text-align:center;">14A</td><td><a href="/csci-315/lectures/25-project3">Brainstorm Optimizations for Project 3</a></td><td></td></tr><tr><td style="text-align:center;">14B</td><td><em>Thanksgiving</em> (No Class)</td><td></td></tr><tr><td style="text-align:center;">15A</td><td><a href="/csci-315/lectures/26-review">Comparison of Data-Structure Performance</a></td><td></td></tr><tr><td style="text-align:center;">15B</td><td><a href="/csci-315/guides/final-study-guide">Final Exam (Part 1)</a></td><td></td></tr><tr><td style="text-align:center;">16B</td><td><a href="/csci-315/guides/final-study-guide">Final Exam (Part 2)</a> at 10:30 a.m. <a href="https://www.charlestonsouthern.edu/academics/academic-calendar/" target="_blank" rel="noreferrer">per the official exam schedule</a></td><td></td></tr></tbody></table><h3 id="online-students" tabindex="-1">Online Students <a class="header-anchor" href="#online-students" aria-label="Permalink to “Online Students”">​</a></h3><p>Be aware that the lack of scheduled face-to-face communication puts online students at a disadvantage. Therefore, communication is paramount. I will answer email during office hours. Please keep assignment due dates in mind, because there may be a delay in my response time. In short, get started early and stay ahead!</p><h4 id="video-recording-of-lectures" tabindex="-1">Video Recording of Lectures <a class="header-anchor" href="#video-recording-of-lectures" aria-label="Permalink to “Video Recording of Lectures”">​</a></h4><p>I will video-record my in-class lectures and post the links on <a href="https://csu-cs.github.io/csci-315/" target="_blank" rel="noreferrer">the course website</a>. These recordings are for online students so they can review the material. Lecture videos from the previous semester are currently posted so you can work ahead.</p><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to “Grading”">​</a></h2><p>The assessment categories are weighted as follows.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Task</th><th style="text-align:right;">Percentage</th></tr></thead><tbody><tr><td style="text-align:right;">Ethics Paper</td><td style="text-align:right;">5%</td></tr><tr><td style="text-align:right;">Labs</td><td style="text-align:right;">36%</td></tr><tr><td style="text-align:right;">Projects</td><td style="text-align:right;">30%</td></tr><tr><td style="text-align:right;">Midterm</td><td style="text-align:right;">14%</td></tr><tr><td style="text-align:right;">Final</td><td style="text-align:right;">15%</td></tr></tbody></table><h3 id="grading-scale-for-letter-grade" tabindex="-1">Grading Scale for Letter Grade <a class="header-anchor" href="#grading-scale-for-letter-grade" aria-label="Permalink to “Grading Scale for Letter Grade”">​</a></h3><p>Final letter grades will be calculated using the following ranges.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Letter Grade</th><th style="text-align:left;">Grade Range %</th><th style="text-align:left;">Grade Points per Credit</th></tr></thead><tbody><tr><td style="text-align:left;">A</td><td style="text-align:left;">90% and 100%</td><td style="text-align:left;">4.0</td></tr><tr><td style="text-align:left;">B+</td><td style="text-align:left;">87% and &lt; 90%</td><td style="text-align:left;">3.5</td></tr><tr><td style="text-align:left;">B</td><td style="text-align:left;">80% and &lt; 87%</td><td style="text-align:left;">3.0</td></tr><tr><td style="text-align:left;">C+</td><td style="text-align:left;">77% and &lt; 80%</td><td style="text-align:left;">2.5</td></tr><tr><td style="text-align:left;">C</td><td style="text-align:left;">70% and &lt; 77%</td><td style="text-align:left;">2.0</td></tr><tr><td style="text-align:left;">D</td><td style="text-align:left;">60% and &lt; 70%</td><td style="text-align:left;">1.0</td></tr><tr><td style="text-align:left;">F</td><td style="text-align:left;">less than 60%</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;">FA</td><td style="text-align:left;">Failure for Absences</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;">FD</td><td style="text-align:left;">Academic Dishonesty</td><td style="text-align:left;">0</td></tr></tbody></table><h3 id="late-work" tabindex="-1">Late Work <a class="header-anchor" href="#late-work" aria-label="Permalink to “Late Work”">​</a></h3><p>If a lab or project is submitted within 7 days of the deadline and before the last day of class, the work will earn 80% credit. After 7 days, the work will earn 0% credit. Late work will <strong>not</strong> be accepted after the final day of class (before finals). Exams and papers may <strong>not</strong> be submitted late.</p><h3 id="teamwork-and-assistance" tabindex="-1">Teamwork and Assistance <a class="header-anchor" href="#teamwork-and-assistance" aria-label="Permalink to “Teamwork and Assistance”">​</a></h3><p>There are no group projects in this course. All work is to be completed individually without any assistance from students, online tutoring, generative AI, or other services. You may seek help from your professor.</p><p>Because this class is difficult, do not allow yourself to fall behind. There is a significant snowball potential. Significantly more work is required compared to previous classes. Expect to put <em>many</em> hours into the projects (10, 20, or 30 hours depending on your skill). <strong>Do not</strong> wait until the last moment. <strong>Do</strong> come to me for help during office hours. <strong>Do</strong> discuss your designs and ideas with me and not just your programming bugs.</p><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to “Attendance”">​</a></h2><p>Student participation is crucial for academic success. Students are also expected to check their BucMail daily and review Blackboard for course announcements.</p><h3 id="in-person" tabindex="-1">In-Person <a class="header-anchor" href="#in-person" aria-label="Permalink to “In-Person”">​</a></h3><p>Any student who misses 25% of course meetings will be awarded a grade of FA (Failure due to Absences). In this course, <strong>FA is awarded after missing 7 class meetings</strong>. Three (3) instances of tardiness or leaving class early are equal to one absence. For more information, please see the <a href="https://www.charlestonsouthern.edu/wp-content/uploads/policy-r-10-revised-sept-2025.pdf" target="_blank" rel="noreferrer">CSU Excessive Absence Policy</a>. If you arrive after the roll is called, check in with the professor directly after class so that you will be recorded as tardy instead of absent.</p><h3 id="online" tabindex="-1">Online <a class="header-anchor" href="#online" aria-label="Permalink to “Online”">​</a></h3><p>Students are expected to log in to their course(s) daily, watch lecture videos, and complete readings and assignments. Students are also expected to check their BUCmail daily.</p><p>Any student who does not <strong>participate</strong> in this course&#39;s academic activities for 28 consecutive days will be awarded a grade of FA (Failure due to Absences). Academic activities include completing assignments, quizzes, and exams (simply logging in does <strong>not</strong> count as attendance). For more information, please see <a href="https://www.charlestonsouthern.edu/wp-content/uploads/policy-r-10-revised-sept-2025.pdf" target="_blank" rel="noreferrer">CSU&#39;s Excessive Absences policy</a>.</p><h2 id="course-department-and-university-policies" tabindex="-1">Course, Department, and University Policies <a class="header-anchor" href="#course-department-and-university-policies" aria-label="Permalink to “Course, Department, and University Policies”">​</a></h2><h3 id="academic-integrity-and-the-honor-code" tabindex="-1">Academic Integrity and the Honor Code <a class="header-anchor" href="#academic-integrity-and-the-honor-code" aria-label="Permalink to “Academic Integrity and the Honor Code”">​</a></h3><p>All students are expected to adhere to <a href="https://www.charlestonsouthern.edu/wp-content/uploads/CSU-Policy-R-58-updated-April-2026.pdf" target="_blank" rel="noreferrer">Charleston Southern University&#39;s Academic Integrity Policy</a> and the <a href="/csci-315/integrity">Computer Science Departmental Guidelines</a>. <strong>All assignments</strong> are individual assignments unless explicitly specified by the professor. Do not collaborate, search for posted solutions, or post code online. <strong>Make sure that you write every line of your own code.</strong> You should not use <strong>ANY</strong> outside sources of code. Referencing code written by someone else (including AI) or sharing your code with others (online or in-person) is considered a violation of the Academic Integrity Policy and will be reported to the registrar&#39;s office. <strong>Publicly posting code related to assignments is prohibited</strong> (e.g., <strong>don&#39;t</strong> post to forums, blogs, public repositories, chegg.com, etc.). Do NOT look at your neighbor&#39;s screen for hints or ask, &quot;how did you do that?&quot;, unless you talk to me <strong>beforehand</strong>.</p><ul><li><p><strong>NEVER</strong> look at someone else&#39;s code in person or online (chegg.com, forums, email, etc.).<br><strong>Do</strong> ask your professor if you have questions or get stuck.</p></li><li><p><strong>NEVER</strong> search online for assignment solutions.<br><strong>Do</strong> reference code from the book, code given to you by the instructor, and online documentation on the C++ language.</p></li><li><p><strong>NEVER</strong> exchange code in any manner, or you tell someone what code they need.<br><strong>You may</strong> talk to your classmates about C++ or assignments if you are not sharing ideas for assignment solutions.</p></li><li><p><strong>NEVER</strong> use an AI tool to generate code for use in an assignment or exam without explicit permission from the instructor for that particular task. As an example, Visual Studio Code extensions that generate code (like GitHub Copile, Tabnine, and Cody) are prohibited.<br><strong>You may</strong> use AI to help explain concepts or study before exams, but not for any use for planning, debugging, developing, or any other use for assignments, exams, or other assessments.</p></li></ul><h3 id="ai-policy-for-csci-315" tabindex="-1">AI Policy for CSCI 315 <a class="header-anchor" href="#ai-policy-for-csci-315" aria-label="Permalink to “AI Policy for CSCI 315”">​</a></h3><p><strong>Level 1: Use of generative AI is <em>prohibited</em> in this course.</strong></p><p>To ensure mastery of the concepts and skills in this course, the use of generative artificial intelligence (AI) tools is prohibited. Students who are unsure of this policy or any assignment-specific directions, including whether a given technology is considered AI, should consult the course instructor before using such technology to complete their assignment.</p><p>While proper AI use is an important skill that will be emphasized in other courses, AI misuse short-circuits the learning process to give the illusion of proficiency without the necessary depth. It is unethical to take full credit for work created with the help of AI. This principle is the same as using someone else’s idea without citing it.</p><p><a href="/csci-315/integrity#artificial-intelligence-ai">Review the departmental policies for AI use in Computer Science coursework.</a></p><p><a href="/csci-315/integrity">Click here for additional guidance on academic integrity for Computer Science coursework.</a></p><h3 id="a-community-of-honor" tabindex="-1">A Community of Honor <a class="header-anchor" href="#a-community-of-honor" aria-label="Permalink to “A Community of Honor”">​</a></h3><blockquote><p>As a liberal arts university committed to the Christian faith, Charleston Southern University seeks to develop ethical men and women of disciplined, creative minds and lives, focusing on leadership, service, and learning. The Honor System of Charleston Southern University is designed to provide an academic community of trust in which students can enjoy the opportunity to grow both intellectually and personally. For these purposes, the following rules and guidelines will be applied.</p></blockquote><h3 id="academic-dishonesty" tabindex="-1">Academic Dishonesty <a class="header-anchor" href="#academic-dishonesty" aria-label="Permalink to “Academic Dishonesty”">​</a></h3><blockquote><p>“<em>Academic Dishonesty</em>” is the transfer, receipt, or use of academic information, or the attempted transfer, receipt, or use of academic information in a manner not authorized by the instructor or by university rules. It includes, but is not limited to, cheating, plagiarism, and forgery as well as aiding or encouraging another to commit academic dishonesty.</p></blockquote><blockquote><p>“<em>Cheating</em>” is defined as wrongfully giving, taking, or presenting any information or material borrowed from another source (including the Internet) by a student with the intent of aiding themself or another in academic work. This includes, but is not limited to, a test, examination, presentation, experiment, or any written assignment, which is considered in any way in the determination of the final grade. Using AI in violation of a course or assessment’s stated AI protocol is cheating.</p></blockquote><blockquote><p>“<em>Plagiarism</em>” is the taking or attempted taking of an idea, a writing, a graphic, music composition, art, or datum of another person or Artificial Intelligence (AI) tool without giving proper credit and presenting or attempting to present it as one&#39;s own, with or without intent. It is also taking written material of one&#39;s own that have been used for a previous course assignment and using it without reference to it in its original form. Any use of AI models without proper citation is plagiarism.</p></blockquote><blockquote><p>Students are encouraged to ask their instructor(s) for clarification regarding their academic dishonesty standards. Instructors will include academic dishonesty/integrity standards, including explicit permissible AI use, on their course syllabi and each individual assignment.</p></blockquote><p>Violations of this policy will result in academic discipline, up to and including expulsion from the University.</p><p>For more information on procedures and violation appeals, refer to the <a href="https://www.charlestonsouthern.edu/current-students/student-resources/" target="_blank" rel="noreferrer">Student Handbook</a>.</p><h3 id="course-evaluations" tabindex="-1">Course Evaluations <a class="header-anchor" href="#course-evaluations" aria-label="Permalink to “Course Evaluations”">​</a></h3><p>To pursue our mission of <em>Academic Excellence in a Christian Environment</em>, we must receive feedback from students. The student feedback survey is online and will be available to students in the second half of the semester. Students are strongly encouraged to complete the short evaluation survey, which is anonymous. Your professor will let you know when the survey is available. The survey will be available through your MyCSU account. We greatly value your opinion!</p><h3 id="student-representatives" tabindex="-1">Student Representatives <a class="header-anchor" href="#student-representatives" aria-label="Permalink to “Student Representatives”">​</a></h3><p>These are students who are designated by letter to represent the University in official business (e.g., athletic, music, and similar events). If officially scheduled absences cause these students to miss tests, assignments, or similar academic activities, university policy allows these to be made up without penalty. Student Representatives may opt to either make-up tests <em>before</em> departure or supplant missed tests with the final exam grade. Final exams must always be taken <em>before</em> departure to avoid an Incomplete for the course. Scheduled assignments remain subject to the lateness policy and must be turned in before departure to avoid lateness penalties. Student Representatives are responsible for informing the instructor of official absences and to make all appropriate arrangements.</p><h3 id="internet-etiquette" tabindex="-1">Internet Etiquette <a class="header-anchor" href="#internet-etiquette" aria-label="Permalink to “Internet Etiquette”">​</a></h3><p>Charleston Southern University (CSU) holds students, faculty, and staff to the highest standards of conduct and expects to demonstrate courteous behaviors and practices in online communications. This policy includes guidelines and recommendations for online communications. Being respectful, thoughtful, meaningful, and ethical are fundamental to good netiquette.</p><p>CSU&#39;s basic netiquette rules are:</p><ul><li><p>Course communications are for internal use only and are considered confidential. Do not forward or quote discussion posts, emails, or other course communications to outside parties.</p></li><li><p>Never share personal login usernames, IDs, or passwords.</p></li><li><p>Do not type in all capital letters. It is perceived online as shouting.</p></li><li><p>Use proper capitalization, grammar, spelling, and punctuation conventions for professional communications.</p></li><li><p>Avoid texting jargon or abbreviations without explanation.</p><ul><li><p>Incorrect: &quot;CSU is a wonderful university.&quot;</p></li><li><p>Correct: &quot;Charleston Southern University (CSU) is a wonderful university.&quot;</p></li></ul></li><li><p>Be mindful of sending emails. Ensure that content is relevant and pay attention to <em>Reply</em> versus <em>Reply All</em>.</p></li><li><p>BucMail is the only email allowed for course communications. Other platforms (Yahoo, Gmail, etc.) are prohibited.</p></li><li><p>In video conferencing, mute your microphone when not speaking.</p></li><li><p>Differing views are natural and welcome in discussion boards. Be respectful in your comments, even if you disagree or dislike someone&#39;s position on a topic.</p></li><li><p>Respect the time and availability of students, faculty, and staff. Emails should be addressed within one business day. Remember that traditional faculty work hours are 8 a.m. - 5 p.m. EST.</p></li></ul><h3 id="accessibility-services" tabindex="-1">Accessibility Services <a class="header-anchor" href="#accessibility-services" aria-label="Permalink to “Accessibility Services”">​</a></h3><p>Any student who may need accommodations should review the requirements/procedures on the <a href="https://www.charlestonsouthern.edu/student-life/student-support/student-success/accessibility-services/" target="_blank" rel="noreferrer">Accessibility Services website</a>. Once approved to receive accommodations, the student must contact the instructor.</p><h3 id="title-ix-confidentiality-and-responsible-employee-statement" tabindex="-1">Title IX: Confidentiality and Responsible Employee Statement <a class="header-anchor" href="#title-ix-confidentiality-and-responsible-employee-statement" aria-label="Permalink to “Title IX: Confidentiality and Responsible Employee Statement”">​</a></h3><p>Charleston Southern University is committed to maintaining a safe learning environment for everyone. In accordance with Title IX of the Education Amendments of 1972, the university prohibits any form of sexual harassment, including quid pro quo harassment, hostile environments, sexual assault, dating/domestic violence, and stalking. This policy applies to all students, employees, and visitors.</p><p>Additionally, Title IX prohibits discrimination against students based on pregnancy, childbirth, false pregnancy, termination of pregnancy, or recovery from these conditions. Pregnant or parenting students may receive accommodations to ensure their full participation in educational programs. These adjustments can be arranged through the university’s Title IX Coordinator or their designee.</p><p>Under Charleston Southern University’s Title IX Policy, all faculty members, including teaching assistants, are required to report any disclosures of sex or gender-based discrimination or violence to the Title IX Coordinator. The Title IX Coordinator will provide support and resources while maintaining privacy. If you or someone you know needs assistance, please contact the Title IX Coordinator:</p><p>Summer Cora<br> (843)-863-7374<br><a href="mailto:titleix@csuniv.edu" target="_blank" rel="noreferrer">titleix@csuniv.edu</a><br> Office Location: 2nd floor of the Student Center</p><p>Please visit the <a href="https://www.charlestonsouthern.edu/offices/title-ix/" target="_blank" rel="noreferrer">CSU Title IX webpage</a> for more information on Title IX procedures, anonymous reporting, or available support.</p><hr><p>See all course, department, and university policies located in <a href="https://csuniv.blackboard.com" target="_blank" rel="noreferrer">Blackboard</a> and the <a href="https://www.charlestonsouthern.edu/current-students/student-resources/" target="_blank" rel="noreferrer">CSU Student Handbook</a>.</p>',84)])]))}});export{k as __pageData,C as default};
